# Computationally efficient solution to count disjoint triangle pairs

def solution(input_str):
    import sys
    input_data = input_str.strip().split('\n')
    n = int(input_data[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, input_data[i].split())
        points.append((x, y))

    # Signature to detect if triangles overlap
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Get the orientation of three points
    def get_orientation(o, a, b):
        val = cross_product(o, a, b)
        if val == 0:
            return 0
        if val > 0:
            return 1  # Counter-clockwise
        return 2  # Clockwise

    # Check if point p is inside or on triangle abc
    def point_in_triangle(p, a, b, c):
        o1 = get_orientation(p, a, b)
        o2 = get_orientation(p, b, c)
        o3 = get_orientation(p, c, a)

        if o1 == 0 or o2 == 0 or o3 == 0:
            return True  # On an edge

        if o1 != 0 and o1 != 2 and o2 != 0 and o2 != 2 and o3 != 0 and o3 != 2:
            return True
        return False

    # Check if two triangles share any edge (sect or share points)
    def triangles_overlap(abc, def_tri):
        # check if any vertex of abc is in def or if any vertex of def is in abc
        for pt in abc:
            if point_in_triangle(pt, def_tri[0], def_tri[1], def_tri[2]):
                return True
        for pt in def_tri:
            if point_in_triangle(pt, abc[0], abc[1], abc[2]):
                return True
        return False

    # Generate all triangles
    triangles = []
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                triangles.append([i, j, k])  # store indices

    total = 0
    eta = len(triangles)

    for i in range(eta):
        for j in range(i + 1, eta):
            t1 = triangles[i]
            t2 = triangles[j]

            # Quick check: do they share any vertices?
            if len(set(t1) & set(t2)) > 0:
                continue

            t1_pts = [points[t1[0]], points[t1[1]], points[t1[2]]]
            t2_pts = [points[t2[0]], points[t2[1]], points[t2[2]]]

            if not triangles_overlap(t1_pts, t2_pts):
                total += 1

    return str(total) + '\n'
