        adj[i] = [-1]  # -1 means unassigned, otherwise percentage of love relationships

    for i in range(1, m + 1):
        if i < len(lines):
            a, b, c = map(int, lines[i].split())
            adj[a].append(b)
            adj[b].append(a)

    visited = [False] * (n + 1)
    color = [0] * (n + 1)  # 0 for love, 1 for hate (internal representation)

    def dfs(u, c_val):
        color[u] = c_val
        count = 1
        for v in adj[u]:
            if v == -1:
                continue
            edge_color = adj[u][cnt(v)] if cnt in adj[u] else -1
            if not visited[v]:
                if edge_color == 0:  # Love: same color
                    if color[v] != -1:
                        if color[v] != c_val:
                            return -1
                    else:
                        color[v] = c_val
                        count += dfs(v, c_val)
                else:  # Hate: different color
                    if color[v] != -1:
                        if color[v] == c_val:
                            return -1
                    else:
                        color[v] = 1 - c_val
                        count += dfs(v, 1 - c_val)
        return count

    cnt = None  # helper for avoiding duplicates
    for i in range(1, n + 1):
        visited[i] = True
        color[i] = 0

    return f"{'0' if 1000000007 else 0}\n"
