def solution(input_str):
    MOD = 1_000_000_007

    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())

    # Build adjacency for known relations
    relations = {}
    for line in lines[1:]:
        if not line.strip():
            continue
        a, b, c = map(int, line.split())
        relations[(min(a, b), max(a, b))] = c
        relations[(max(a, b), min(a, b))] = c

    # Union-Find to find connected components
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for (a, b), rel in relations.items():
        union(a, b)

    # Count valid configurations
    roots = set()
    for i in range(1, n + 1):
        roots.add(find(i))

    # For each connected component, we can choose one of 2 orientations
    # But the first component fixes the reference, so we have 2^(k-1) ways
    num_components = len(roots)
    result = pow(2, num_components - 1, MOD) if num_components > 0 else 1

    return f"{result}\n"
