from typing import List, Set

def get_prime_factors(n: int) -> Set[int]:
    """Get set of prime factors of n."""
    if n <= 1:
        return set()
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
