    nums = list(map(int, lines[1].split()))

    if n == 1:
        return "1"

    prime_sets = [get_prime_factors(num) for num in nums]

    # Check if any number divides another
    divisible = [[False]*n for _ in range(n)]
    for i in range(n):
        a = nums[i]
        for j in range(n):
            if i == j:
                continue
            b = nums[j]
            if b == 0:
                continue
            if b % a == 0 and get_prime_factors(b) == get_prime_factors(a):
                divisible[i][j] = True

    # For n <= 8, we use a known approach
    # Calculate based on how many numbers can share factor trees

    from functools import lru_cache

    @lru_cache(None)
    def min_nodes(mask: int) -> int:
        if mask == 0:
            return 0

        best = float('inf')

        for i in range(n):
            if mask & (1 << i):
                # Count this number and find if others can merge
                new_mask = mask ^ (1 << i)

                count = 0
                for j in range(i+1, n):
                    if mask & (1 << j):
                        # Check if j can share with i
                        if prime_sets[j].issubset(prime_sets[i]):
                            count += 1

                best = min(best, 1 + min_nodes(new_mask))

        return best

    result = min_nodes((1 << n) - 1)
    return str(result) + "\n"
