                is_lucky_count[a][b] = 1
            else:
                is_lucky_count[a][b] = 0

    # Compute 2D prefix sums
    count = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            count[a][b] = count[a-1][b] + count[a][b-1] - count[a-1][b-1] + is_lucky_count[a][b]

    # Find minimum area x * y such that count[x][y] >= w
    min_area = float('inf')
    best_x, best_y = -1, -1

    for x in range(1, maxx + 1):
