        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    neighbors.append((ni, nj))
        return neighbors

    # Check if a color is valid for position (i, j)
    def is_valid_color(i, j, color):
        for ni, nj in get_neighbors(i, j):
            if grid[ni][nj] == color:
                return False
        return True

    # Validate pre-colored cells first for quick rejection
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                color = grid[i][j]
                for ni, nj in get_neighbors(i, j):
                    if grid[ni][nj] == color:
                        return '0'

    # Backtracking to fill empty cells
    def backtrack(cell_idx):
        if cell_idx == n * m:
            return True

        i, j = cell_idx // m, cell_idx % m

        if grid[i][j] != '0':
            return backtrack(cell_idx + 1)

        for color in ['1', '2', '3', '4']:
            if is_valid_color(i, j, color):
                grid[i][j] = color
                if backtrack(cell_idx + 1):
                    return True
                grid[i][j] = '0'

        return False

    if backtrack(0):
        result = []
        for row in grid:
            result.append(''.join(row))
        return '\n'.join(result)
    else:
        return '0'
