            if 0 < offset < 4:
                if 1 <= y - td:
                    x += td
                    y -= td
            positions[offset] = (x, y)
        transformer_positions[key] = positions

    # Process grid in row-major order with proper time tracking
    for i in range(N):
        for j in range(M):
