            if j > 0:
                from_cells.append((i, j - 1))

            for pi, pj in from_cells:
                time_reached = i + j + 1
                energy_here = dp[pi][pj]

                if energy_here >= min_energy:
                    continue

                min_energy = energy_here
                arrival_time = time_reached

                # Check for transformers at this position and time
                transformer_energy = 0
                for (tx, ty, td, start_t, energy) in transformers:
                    if start_t <= arrival_time:
