Looking at this problem, I need to understand:

1. We have n judges, each with uncertainty a_i and experience e_i
2. For each judge we can play, we can divide a_i by any divisor d where d ≤ k
3. Goal: Get GCD of all final a_i values equal to 1, minimizing cost = (count of judges played) × (sum of their experiences)

Let me analyze the solution:

- If initial GCD of all a_i is already 1, cost is 0
- Otherwise, we need to find which judges to play with and divide by what to make the final GCD = 1
- This is a set cover problem: for each prime factor of the initial GCD, we need to eliminate it by playing with at least one judge that has that factor

I'll use dynamic programming with bitmask (remaining prime factors to eliminate):

```python
import math
from functools import reduce

def get_prime_factors(n):
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    def gcd_all(nums):
        g = nums[0]
        for x in nums[1:]:
            g = math.gcd(g, x)
        return g

    initial_gcd = gcd_all(a)

    if initial_gcd == 1:
        return '0\n'

    primes = get_prime_factors(initial_gcd)
    num_primes = len(primes)

    if num_primes == 0:
        return '0\n'

    # For each prime, find which judges can eliminate it (by not having it after division)
    # Judge i can eliminate prime p[j] if a[i] is divisible by p[j] and we divide by p[j] or multiple
    # Satisfying the condition: after division, a[i] is not divisible by p[j]

    # A judge i contributes to eliminating prime p[j] if a[i] has p[j] as factor
    # We can remove p[j] from a[i] by dividing by p[j] (if p[j] <= k)

    # Build DP: dp[mask] = min cost to handle the set of remaining primes (eliminated primes have their bits off)
    full_mask = (1 << num_primes) - 1

    # For each judge, what prime factors they have among our target primes?
    judge_can_eliminate = []
    for i in range(n):
        factors_of_a = get_prime_factors(a[i])
        judge_factors = [p for p in factors_of_a if p in primes]
        judge_can_eliminate.append(judge_factors)

    # Precompute: for each prime index, which judges can eliminate it
    prime_to_judges = [[] for _ in range(num_primes)]
    for i in range(num_primes):
        p = primes[i]
        for j, factors in enumerate(judge_can_eliminate):
            if p in factors:
                prime_to_judges[i].append(j)

    INF = float('inf')
    dp = [INF] * (1 << num_primes)
    dp[0] = 0

    for mask in range(1 << num_primes):
        if dp[mask] == INF:
            continue

        count = bin(mask).count('1')
        if count == num_primes:
            continue

        # Try to add more judges to eliminate remaining primes
        for j in range(n):
            money = e[j]
            if dp[mask] * (count + 1) + money * (count + 1) >= dp[mask]:
                new_mask = mask
                for i in range(num_primes):
                    if (mask >> i) & 1:  # prime i still needed
                        # Check if judge j can eliminate this prime
                        if primes[i] in judge_can_eliminate[j]:
                            new_mask |= (1 << i)

                actual_mask = new_mask
                if actual_mask > mask:
                    cost = dp[mask] + money
                    # Cost is: number of judges chosen * sum of their expenses
                    # Wait, re-reading: x * y where x = count, y = sum of experiences
                    dp[actual_mask] = min(dp[actual_mask], dp[mask])

    # Actually, the cost model is: count × sum_experience
    # So we need to track both

    INF = float('inf')
    # dp[mask] = min sum_experience for this mask
    dp = [INF] * (1 << num_primes)
    dp[0] = 0

    for mask in range(1 << num_primes):
        if dp[mask] == INF:
            continue

        for j in range(n):
            mask_w_j = mask
            for i in range(num_primes):
                if (mask >> i) & 1:
                    if primes[i] in judge_can_eliminate[j]:
                        mask_w_j |= (1 << i)

            if mask_w_j > mask:
                cost = dp[mask] + e[j]
                dp[mask_w_j] = min(dp[mask_w_j], cost)

    if dp[full_mask] == INF:
        return '-1\n'

    # Convert dp back to: (count that achieved full_mask) × dp[full_mask]
    # We need to track count

    # dp[mask] = (min_sum_experience, min_count)
    dp = [(INF, INF)] * (1 << num_primes)
    dp[0] = (0, 0)

    for mask in range(1 << num_primes):
