            edges.append((i, u, v, w))
            if u == 1 or v == 1:
                capital_edges.append((i, u, v, w))

    # If not enough capital edges
    if len(capital_edges) < k:
        return '-1\n'

    idx_cap_map = {idx: (u, v, w) for idx, u, v, w in capital_edges}
    idx_non_cap_map = {idx: (u, v, w) for idx, u, v, w in edges if u != 1 and v != 1}

    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        px, py = find(parent, x), find(parent, y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    result = []

    # Add k capital edges
    for idx in sorted(idx_cap_map.keys(), key=lambda x: idx_cap_map[x][2])[:k]:
        u, v, _ = idx_cap_map[idx]
        if union(parent, rank, u, v):
            result.append(idx)

    # Add non-capital edges
    for idx in sorted(idx_non_cap_map.keys(), key=lambda x: idx_non_cap_map[x][2]):
        u, v, _ = idx_non_cap_map[idx]
        if union(parent, rank, u, v):
            result.append(idx)
            if len(result) >= n - 1:
                break

    if len(result) == n - 1:
        capital_in = sum(1 for idx in result if idx in idx_cap_map)
        if capital_in == k:
            return str(n - 1) + '\n' + ' '.join(map(str, result)) + '\n'

    # Try swapping capitals for non-capitals
    if result:
        result2 = [idx for idx in result if idx in idx_cap_map][:k]
        result2.extend(idx for idx in sorted(idx_non_cap_map.keys(), key=lambda x: idx_non_cap_map[x][2]) if idx not in result2)
        if len(result2) == n - 1:
            return str(n - 1) + '\n' + ' '.join(map(str, result2)) + '\n'

    return '-1\n'
