    # If n=1, no solution exists (no prime has order 1 mod p where b^n-1 is divisible)
    if n == 1:
        return "-1\n"

    # Precompute divisors of n in sorted order
    def get_divisors(num):
        divs = []
        i = 1
        while i * i <= num:
            if num % i == 0:
                divs.append(i)
                if i*i != num:
                    divs.append(num // i)
        return sorted(divs)

    divs = get_divisors(n)

    # Simple primality test
    def is_prime(num):
        if num < 2:
            return False
        if num < 4:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # Modular exponentiation
    def pow_mod(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            b //= 2
        return result

    # Generate primes up to limit using sieve
    def sieve(limit):
        primes = []
        is_prime = bytearray([1]) * (limit + 1)
        is_prime[0] = is_prime[1] = 0
        for i in range(2, limit + 1):
            if is_prime[i]:
                primes.append(i)
                for j in range(i*i, limit + 1, i):
                    is_prime[j] = 0
        return primes

    # Find primes ≡ 1 (mod n) up to limit
    def get_primes_congruence(n, limit):
        primes = sieve(limit)
        result = []
        for p in primes:
            if p > 1 and p % n == 1:
                result.append(p)
        return result

    # Search for valid base from x-1 down to 2
    for b in range(x - 1, 1, -1):
        if b == 1:
            continue

        # Look for prime p ≡ 1 (mod n) where order of b mod p is exactly n
        # We need to search for primes - try reasonable limits
        limit = 2000000
        primes = get_primes_congruence(n, limit)

        for p in primes:
            # Check if condition might allow order n
            # We need b^n ≡ 1 (mod p)
            if pow_mod(b, n, p) != 1:
                continue

            # Find the actual order of b mod p by checking divisors
            # in increasing order (to find smallest order first)
            order = n
            for d in divs:
                if d == n:
                    break  # if we reach n and no smaller divisor worked, order is n
                if pow_mod(b, d, p) == 1:
                    order = d
                    break

            if order == n:
                return str(b) + "\n"

        # If not found in first limit increase
        if len(primes) < 100:
            # Try with larger limit
            limit = min(5000000, x * 10)
            primes = get_primes_congruence(n, limit)
            for p in primes:
                if pow_mod(b, n, p) == 1:
                    order = n
                    for d in divs:
                        if d == n:
                            break
                        if pow_mod(b, d, p) == 1:
                            order = d
                            break
                    if order == n:
                        return str(b) + "\n"

    return "-1\n"


