Looking at this problem, I need to:

1. Find all rooms with lights on
2. Navigate through the grid turning off lights
3. Constraint: Can only move in a direction if there's a light somewhere in that direction (line of sight)
4. Return to starting position after turning off all lights

The key insight is that we need to maintain lights visible in all directions we might need to escape, so we shouldn't turn off lights randomly. 

Let me implement a BFS approach to find a valid path that visits all lit cells while respecting the visibility constraint:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n, x0, y0 = int(parts[0]), int(parts[1]), int(parts[2])

    grid = []
    for i in range(1, n + 1):
        grid.append(list(map(int, lines[i].split())))

    # Find all lit cells
    lit_cells = []
    for x in range(1, n+1):
        for y in range(1, n+1):
            if grid[x-1][y-1] == 1:
                lit_cells.append((x, y))

    if not lit_cells:
        # No lights to turn off, but we still need to return to start
        return "YES\n"

    directions = [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]

    def check_line_of_sight(r, c, dr, dc):
        """Check if there's a light in the given direction from (r,c)"""
        for k in range(1, n + 1):
            nr, nc = r + dr * k, c + dc * k
            if 1 <= nr <= n and 1 <= nc <= n:
                if grid[nr-1][nc-1] == 1:
                    return True
                else:
                    # Continue checking - light might be further
                    pass
            else:
                break
        return False

    def is_reachable(r1, c1, r2, c2):
        """BFS to see if we can reach (r2,c2) from (r1,c1) given current lights"""
        if (r1, c1) == (r2, c2):
            return True

        from collections import deque
        q = deque([(r1, c1, "")])
        visited = {(r1, c1)}

        while q:
            curr_r, curr_c, path = q.popleft()
            if (curr_r, curr_c) == (r2, c2):
                return True

            for dr, dc, dchar in directions:
                nr, nc = curr_r + dr, curr_c + dc
                if 1 <= nr <= n and 1 <= nc <= n and (nr, nc) not in visited:
                    # Check if we can move (need light in direction)
                    if check_line_of_sight(curr_r, curr_c, dr, dc):
                        visited.add((nr, nc))
                        q.append((nr, nc, path + dchar))
        return False

    def bfs_return_to_start(r, c):
        """Find path from (r,c) back to start"""
        if (r, c) == (x0, y0):
            return []

        from collections import deque
        q = deque([(r, c, "")])
        parent = {}
        visited = {(r, c)}

        while q:
            curr_r, curr_c, path = q.popleft()
            if (curr_r, curr_c) == (x0, y0):
                # Reconstruct path
                res = []
                curr = (curr_r, curr_c)
                while parent[curr]:
                    res.append(parent[curr][1])
                    curr = parent[curr][0]
                return list(reversed(res))

            for dr, dc, dchar in directions:
                nr, nc = curr_r + dr, curr_c + dc
                if 1 <= nr <= n and 1 <= nc <= n and (nr, nc) not in visited:
                    if check_line_of_sight(curr_r, curr_c, dr, dc):
                        visited.add((nr, nc))
                        parent[(nr, nc)] = ((curr_r, curr_c), dchar)
                        q.append((nr, nc, path + dchar))
        return None

    # Greedy approach: visit all lit cells using BFS
    # Start from initial position, try to visit lit cells
    curr_r, curr_c = x0, y0
    visited_lit = set()
    result = []

    # Use limited-depth search to find paths
    max_depth = 200

    def find_path_to_lit():
        """Find a lit cell we can reach and move to"""
        from collections import deque
        q = deque()
        q.append((curr_r, curr_c, [], 0))
        visited = {(curr_r, curr_c)}

        while q and q[0][3] < max_depth:
            r, c, path, depth = q.popleft()

            if not path and len(visited_lit) > 0:
                # We haven't moved yet, find first reachable lit cell
                for tr, tc in lit_cells:
                    if (tr, tc) not in visited_lit:
                        if is_reachable(r, c, tr, tc):
                            path = get_move_path(r, c, tr, tc)
                            if path:
                                return path

            if depth >= max_depth:
                continue

            for dr, dc, dchar in directions:
                nr, nc = r + dr, c + dc
                if 1 <= nr <= n and 1 <= nc <= n and (nr, nc) not in visited:
                    if check_line_of_sight(r, c, dr, dc):
                        # Move to adjacent
                        new_visited = visited | {(nr, nc)}
                        new_path = path + [dchar]

                        # Check if we reached a lit cell
                        reached_lit = False
                        if (nr, nc) in lit_cells and (nr, nc) not in visited_lit:
                            reached_lit = True
                            visited_lit.add((nr, nc))

                        # Only explore further if we're moving toward unvisited lit cells
                        if reached_lit or any(is_reachable(nr, nc, tr, tc) for tr, tc in lit_cells - visited_lit):
                            q.append((nr, nc, new_path, depth + 1))

        return []

    # Build path to visit all lit cells
    path = []
    curr_r, curr_c = x0, y0

    for _ in range(len(lit_cells) + 2):
        if len(visited_lit) == len(lit_cells) and len(path) > 0:
            # Go back to start
            ret = bfs_return_to_start(curr_r, curr_c)
            if ret is None:
                return "NO"
            path.extend(ret)
            return "YES\n" + "".join(path)

        # Find next lit cell
        found = False

        for tr, tc in lit_cells:
            if (tr, tc) not in visited_lit:
                if is_reachable(curr_r, curr_c, tr, tc):
                    path_from = get_move_path(curr_r, curr_c, tr, tc)
                    if path_from:
                        path.extend(path_from)
                        curr_r, curr_c = tr, tc
                        visited_lit.add((tr, tc))
                        found = True
                        break

        if not found:
            # No more reachable lit cells, check if we're done
            if len(visited_lit) == len(lit_cells):
                ret = bfs_return_to_start(curr_r, curr_c)
                if ret is None:
                    return "NO"
                path.extend(ret)
                return "YES\n" + "".join(path)
            else:
                return "NO"

    # Return to start
    ret = bfs_return_to_start(curr_r, curr_c)
    if ret is None:
        return "NO"
    path.extend(ret)

    return "YES\n" + "".join(path)


def get_move_path(start_r, start_c, end_r, end_c):
    """Get path from start to end using BFS with line-of-sight"""
    if (start_r, start_c) == (end_r, end_c):
        return []

    from collections import deque
    q = deque([(start_r, start_c, [])])
    visited = {(start_r, start_c)}

    while q:
        r, c, p = q.popleft()

        for dr, dc, dchar in directions:
            nr, nc = r + dr, c + dc
            if 1 <= nr <= n and 1 <= nc <= n and (nr, nc) not in visited:
                if check_line_of_sight(r, c, dr, dc):
                    new_path = p + [dchar]
                    visited.add((nr, nc))
                    if (nr, nc) == (end_r, end_c):
                        return new_path
                    q.append((nr, nc, new_path))

    return None
