            return []

        from collections import deque
        q = deque([(start_r, start_c, [])])
        visited = {(start_r, start_c)}

        while q:
            r, c, path = q.popleft()

            for dr, dc, dchar in directions:
                nr, nc = r + dr, c + dc
                if 1 <= nr <= n and 1 <= nc <= n and (nr, nc) not in visited:
