def solve(k):
    """Find the k-th digit in the sequence"""

    def block_len(n):
        """Calculate length of block n (concatenation of 1..n)"""
        if n <= 9:
            return n
        elif n <= 99:
            return 9 + 2 * (n - 9)
        elif n <= 999:
            return 9 + 2 * 90 + 3 * (n - 99)
        else:
            # For larger numbers
            return block_len(999) + 4 * (n - 999)

    cum_sum = 0
    n = 1

    # Find which block contains position k
    while True:
        bl = block_len(n)
        if cum_sum + bl >= k:
            # k is in block n
            offset_in_block = k - cum_sum  # 1-indexed offset within the block
            number = 1
            while True:
                s = str(number)
                l = len(s)
                if offset_in_block <= l:
                    return s[offset_in_block - 1]  # 0-indexed
                offset_in_block -= l
                number += 1
        else:
            cum_sum += bl
            n += 1


