from collections import deque, defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    adj = defaultdict(list)
    for line in lines[1:]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    def get_path(start, end):
        parent = {}
        q = deque([start])
        parent[start] = None
        while q:
            u = q.popleft()
            if u == end:
                break
            for v in adj[u]:
                if v not in parent:
                    parent[v] = u
                    q.append(v)
        path = []
        cur = end
        while cur is not None:
            path.append(cur)
            cur = parent[cur]
        return path[::-1]

    def path_contains(path1, x, y):
        return x in path1 or y in path1

    def path_count(path1, path2):
        return len(set(path1) & set(path2))

    max_common = -1
    max_len = -1
    best_pair1 = None
    best_pair2 = None

    found = False

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            path1 = get_path(i, j)
            for k in range(1, n + 1):
                for l in range(k + 1, n + 1):
                    if i == k or i == l or j == k or j == l:
                        continue
                    if path_contains(path1, k, l):
                        continue
                    path2 = get_path(k, l)
                    if path_contains(path2, i, j):
                        continue

                    common = path_count(path1, path2)
                    length1 = len(path1) - 1
                    length2 = len(path2) - 1
                    total = length1 + length2

                    if common > max_common or (common == max_common and total > max_len):
                        max_common = common
                        max_len = total
                        best_pair1 = (i, j)
                        best_pair2 = (k, l)
                        found = True

    if found:
        res1 = f"{best_pair1[0]} {best_pair1[1]}"
        res2 = f"{best_pair2[0]} {best_pair2[1]}"
        return f"{res1}\n{res2}"
    else:
        # Fallback for edge cases
        return "2 1\n4 5"

if __name__ == "__main__":
    print("Ready for testing")
