    def __init__(self, n, m, grid, start_pos):
        self.n = n
        self.m = m
        self.grid = grid
        self.row = start_pos[0]
        self.col = start_pos[1]
        self.moves = []

        # Map expected direction to actual direction
        # self.dir_map[d] = actual direction (X direction - L/R or Y direction - U/D)
        self.dir_map = {
            'U': 'U', 'D': 'D', 'L': 'L', 'R': 'R'
        }

