        """Get cell content, returns None if out of bounds"""
        if 1 <= r <= self.n and 1 <= c <= self.m:
            return self.grid[r-1][c-1]
        return None

    def set_map(self, uds_swap, lrs_swap):
        if uds_swap:
            self.dir_map['U'] = 'D'
            self.dir_map['D'] = 'U'
        else:
            self.dir_map['U'] = 'U'
            self.dir_map['D'] = 'D'

        if lrs_swap:
            self.dir_map['L'] = 'R'
            self.dir_map['R'] = 'L'
        else:
            self.dir_map['L'] = 'L'
            self.dir_map['R'] = 'R'

