        new_r, new_c = self.row + md_row, self.col + md_col

        if 1 <= new_r <= self.n and 1 <= new_c <= self.m:
            cell = self.grid[new_r-1][new_c-1]
            if cell == '*':
                self.row = -1
                self.col = -1
            elif cell == 'F':
