def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    roads = []
    for i in range(1, m + 1):
        ai, bi = map(int, lines[i].split())
        roads.append((ai, bi))

    def crosses(a1, b1, a2, b2):
        """Check if two road segments cross when vertices are in circular order."""
        # Normalize so a1 < b1 and a2 < b2
        a1, b1 = min(a1, b1), max(a1, b1)
        a2, b2 = min(a2, b2), max(a2, b2)

        # Two chords cross if their endpoints alternate along the circle
        return (a1 < a2 < b1 < b2) or (a2 < a1 < b2 < b1)

    # Build implication graph for 2-SAT
    # Node 2*i = variable i is "outside" (o), Node 2*i+1 = variable i is "inside" (i)
    graph = [[] for _ in range(2 * m)]

    for i in range(m):
        for j in range(i + 1, m):
            if crosses(roads[i][0], roads[i][1], roads[j][0], roads[j][1]):
                # If roads cross, they cannot be on the same side
                # i inside and j inside -> conflict (2*i+1 implies not 2*j+1)
                # i outside and j outside -> conflict (2*i implies not 2*j)
                # This gives us the implication graph edges
                graph[2*i + 1].append(2*j)    # if i inside, j must be outside
                graph[2*j + 1].append(2*i)    # if j inside, i must be outside
                graph[2*j].append(2*i + 1)    # if j outside, i can be inside
                graph[2*i].append(2*j + 1)    # if i outside, j can be inside

    # Kosaraju's algorithm to find SCCs
    visited = [False] * (2 * m)
    order = []

    def dfs1(v):
        visited[v] = True
        for w in graph[v]:
            if not visited[w]:
                dfs1(w)
        order.append(v)

    for v in range(2 * m):
        if not visited[v]:
            dfs1(v)

    # Build reverse graph
    rgraph = [[] for _ in range(2 * m)]
    for v in range(2 * m):
        for w in graph[v]:
            rgraph[w].append(v)

    visited = [False] * (2 * m)
    scc = [-1] * (2 * m)
    scc_count = 0

    def dfs2(v, scc_id):
        visited[v] = True
        scc[v] = scc_id
        for w in rgraph[v]:
            if not visited[w]:
                dfs2(w, scc_id)

    for v in reversed(order):
        if not visited[v]:
            dfs2(v, scc_count)
            scc_count += 1

    # Check satisfiability: if x and ~x in same SCC, impossible
    possible = True
    for i in range(m):
        if scc[2*i] == scc[2*i + 1]:
            possible = False
            break

    if not possible:
        return "Impossible"

    # Build solution using topological ordering of SCCs
    result = []
    for i in range(m):
        # In topological order of SCCs, earlier SCC means we can set to outside
        # Compare SCC indices to determine assignment
        if scc[2 * i + 1] < scc[2 * i]:
            result.append('i')  # inside has earlier/topological precedence
        else:
            result.append('o')  # outside

    return ''.join(result)
